export const playReservationDing=()=>{try{const e=window.AudioContext||window.webkitAudioContext;if(!e)return;const t=new e,n=t.createOscillator(),i=t.createOscillator(),o=t.createGain();n.frequency.setValueAtTime(1318.51,t.currentTime),i.frequency.setValueAtTime(1661.22,t.currentTime),n.type="sine",i.type="sine",o.gain.setValueAtTime(.15,t.currentTime),o.gain.exponentialRampToValueAtTime(1e-4,t.currentTime+1.2),n.connect(o),i.connect(o),o.connect(t.destination),n.start(),i.start(),n.stop(t.currentTime+1.2),i.stop(t.currentTime+1.2)}catch(e){console.warn("Audio notification blocked by browser autoplay policy:",e)}};